NEW_FILES = {'test_ceiling_holes.py': '"""A wall may not stand under a hole in its own ceiling (layout_lint L27, 0.235.0; the factory\'s roadmap 260).\n\nTHE CAPTURED CASE: 0.234.0\'s open-floor table walled the delis\' kitchens from their market aisles along x 7, and their\n2.2 m drop at (8, -4) spans x 6.9..9.1 -- the wall\'s centreline 0.1 m inside the hole\'s edge, its new door under the\nhole, seen in the factory\'s cold run 9338. L27 names such a wall, reading walls as the builder stands them; the table\nslides a hole off a wall it lays, or refuses the pair, and slides one off a WALL pair\'s wall already standing.\n\nFAIL ON 0.234.0: there is no L27 (`ceiling_hole_walls`); the table lays the wall and leaves the hole over it; and the\nlibrary\'s six delis carry their drop over the kitchen wall.\n"""\nimport glob\nimport json\nimport os\nimport sys\n\nimport pytest\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nsys.path.insert(0, HERE)\n\nimport layout_lint                   # noqa: E402\nimport open_floor_rules              # noqa: E402\nimport presets                       # noqa: E402\n\n#: The walls the library stood under a hole before the table: named by L27, not moved by it (see L27\'s docstring).\nBEFORE_THE_TABLE = {("bank", "int_0_1"), ("cbp_town_finale_midbalanced_schemafixed", "int_0_2"),\n                    ("final_stand", "int_0_0")}\n\n\ndef _two_storeys(hole_x=0.75, wall=True, back=(0.0, -5.0, 5.0, 5.0)):\n    """Story 0: rooms front (x -5..0) and back meeting along x = 0, a 0.3 m wall there with a door when `wall`, a door\n    in from the west and one from the east; story 1: one room over both. A 2.2 m hole in story 1\'s floor centred at\n    (hole_x, 0), authored twice as the delis\' drop is: a slab hole and a floor_hole link."""\n    return {"name": "t", "footprint_x": 10.0, "footprint_y": 10.0, "n_stories": 2, "wall_thick": 0.3, "grid": 0.5,\n            "rooms": [{"id": "front", "story": 0, "bounds": [-5.0, -5.0, 0.0, 5.0]},\n                      {"id": "back", "story": 0, "bounds": list(back)},\n                      {"id": "loft", "story": 1, "bounds": [-5.0, -5.0, 5.0, 5.0]}],\n            "partitions": ([{"story": 0, "axis": "Y", "pos": 0.0, "start": -5.0, "end": 5.0,\n                             "openings": [{"kind": "door", "pos": 0.0, "width": 1.25, "tag": "front_to_back"}]}]\n                           if wall else []),\n            "slab_holes": [{"story": 1, "x": hole_x, "y": 0.0, "size_x": 2.2, "size_y": 2.2}],\n            "vertical_links": [{"kind": "floor_hole", "story": 1, "x": hole_x, "y": 0.0, "size_x": 2.2,\n                                "size_y": 2.2, "role": "drop"}],\n            "ext_walls": [{"wall": "W", "story": 0, "openings": [{"kind": "door", "pos": 0.0, "width": 1.25}]},\n                          {"wall": "E", "story": 0, "openings": [{"kind": "door", "pos": 0.0, "width": 1.25}]}]}\n\n\n@pytest.fixture\ndef table(monkeypatch):\n    def use(row):\n        monkeypatch.setattr(open_floor_rules, "RULES", {("front", "back"): row})\n    return use\n\n\ndef test_l27_names_a_wall_under_a_hole_in_its_ceiling():\n    s = _two_storeys()\n    (w,) = layout_lint.ceiling_hole_walls(s)\n    assert (w["wall"], w["index"], w["story"], w["axis"], w["pos"]) == ("int_0_0", 0, 0, "Y", 0.0)\n    assert w["into"] == pytest.approx(0.3) and w["along"] == pytest.approx(2.2)\n    assert len(w["refs"]) == 2                             # the slab hole and its link are one hole\n    (msg,) = [x for x in layout_lint.lint_spec(s, "t")[2] if x.startswith("L27 ")]\n    assert "move the hole clear of the wall" in msg\n\n\ndef test_a_hole_flush_with_the_walls_face_is_its_enclosure_not_over_it():\n    assert layout_lint.ceiling_hole_walls(_two_storeys(hole_x=0.15 + 1.1)) == []      # its edge on the east face\n    (w,) = layout_lint.ceiling_hole_walls(_two_storeys(hole_x=0.10 + 1.1))            # 5 cm past it\n    assert w["into"] == pytest.approx(0.05)\n\n\ndef test_a_wall_cut_by_a_hole_in_its_own_floor_is_not_under_the_hole_above():\n    """final_stand\'s storey-1 walls cross its two-storey atrium: the builder cuts them over storey 1\'s hole (roadmap\n    114), so nothing of them stands under storey 2\'s -- a census of authored partitions counted two that are not\n    there."""\n    s = _two_storeys()\n    s["n_stories"] = 3\n    s["rooms"].append({"id": "attic", "story": 2, "bounds": [-5.0, -5.0, 5.0, 5.0]})\n    s["partitions"] = [{"story": 1, "axis": "Y", "pos": 0.0, "start": -5.0, "end": 5.0}]\n    s["vertical_links"] = []\n    s["slab_holes"] = [{"story": 1, "x": 0.0, "y": 0.0, "size_x": 4.0, "size_y": 4.0},\n                       {"story": 2, "x": 0.0, "y": 0.0, "size_x": 3.0, "size_y": 3.0}]\n    assert layout_lint.ceiling_hole_walls(s) == []\n    s["slab_holes"] = s["slab_holes"][1:]                  # nothing cut under it: the wall stands under the upper one\n    (w,) = layout_lint.ceiling_hole_walls(s)\n    assert w["story"] == 1 and w["along"] == pytest.approx(3.0)\n\n\ndef test_the_table_slides_a_hole_off_the_wall_it_lays(table):\n    table(open_floor_rules.WALL)\n    s = _two_storeys(wall=False)\n    said = open_floor_rules.apply(s)\n    (p,) = s["partitions"]\n    assert (p["axis"], p["pos"], p["start"], p["end"]) == ("Y", 0.0, -5.0, 5.0)\n    # one cell east, the side its centre was on: its west edge on the wall\'s face, the hole and its link as one\n    assert s["slab_holes"][0]["x"] == s["vertical_links"][0]["x"] == 1.25\n    assert any("slid +0.50 m in x" in x for x in said), said\n    assert layout_lint.ceiling_hole_walls(s) == [] and layout_lint.open_floors(s) == []\n    assert open_floor_rules.apply(s) == []\n\n\ndef test_a_hole_that_cannot_open_into_one_room_refuses_the_pair(table):\n    table(open_floor_rules.WALL)\n    s = _two_storeys(wall=False, back=(0.0, -5.0, 2.0, 5.0))     # 2 m wide below: no slide fits a 2.2 m hole in it\n    said = open_floor_rules.apply(s)\n    assert s["partitions"] == [] and s["slab_holes"][0]["x"] == 0.75\n    assert any("REFUSED" in x and "(L27)" in x for x in said), said\n    assert len(layout_lint.open_floors(s)) == 1\n\n\ndef test_a_wall_rows_wall_already_standing_gets_its_hole_slid(table):\n    table(open_floor_rules.WALL)\n    s = _two_storeys()                                     # the wall stands with the hole over it: the delis on 0.234.0\n    said = open_floor_rules.apply(s)\n    assert s["slab_holes"][0]["x"] == s["vertical_links"][0]["x"] == 1.25, said\n    assert layout_lint.ceiling_hole_walls(s) == []\n    assert open_floor_rules.apply(s) == []\n\n\ndef test_a_wall_the_table_did_not_ask_for_keeps_its_hole():\n    s = _two_storeys()                                     # front|back has no row\n    assert open_floor_rules.apply(s) == [] and len(layout_lint.ceiling_hole_walls(s)) == 1\n\n\ndef test_the_library_stands_no_wall_under_a_hole_but_the_three_it_had_before_the_table():\n    named = set()\n    for path in sorted(glob.glob(os.path.join(HERE, "specs", "*.json"))):\n        name = os.path.basename(path)[:-5]\n        if name.startswith("lf_"):\n            continue\n        d = json.load(open(path, encoding="utf-8"))\n        named |= {(name, w["wall"]) for w in layout_lint.ceiling_hole_walls(d)}\n    assert named == BEFORE_THE_TABLE\n\n\ndef test_a_deli_made_from_its_preset_drops_into_its_kitchen():\n    d = presets.make("corner_deli")\n    assert layout_lint.ceiling_hole_walls(d) == []\n    (drop,) = [v for v in d["vertical_links"] if v.get("role") == "vertical_attack_angle"]\n    kitchen = [r for r in d["rooms"] if r["id"] == "kitchen"][0]["bounds"]\n    assert kitchen[0] <= drop["x"] - drop["size_x"] / 2.0 and drop["x"] + drop["size_x"] / 2.0 <= kitchen[2]\n'}
CHANGELOG = '## [0.235.0] - a wall may not stand under a hole in its ceiling (layout_lint L27); the open-floor table slides a hole off a wall it stands\n\n**The factory\'s roadmap 260.** 0.234.0\'s table walled the six delis\' kitchens from their market aisles along x 7\n(`market_aisles|kitchen`, WALL), and their 2.2 m "vertical attack angle" drop at (8, -4) -- a `slab_holes` entry and a\nfloor_hole link, one hole -- spans x 6.9..9.1: the new wall\'s centreline 0.1 m inside the hole\'s edge, its new door\nunder the hole, the wall\'s 0.35 m top showing in it. Seen in the factory\'s cold run 9338 (restaurant_row_001, deli_a03)\nin frames of the hole from the kitchen and from above, and by Level Factory\'s drop-edge gate as 7 fewer unguarded\nedges, its column probe reading the wall\'s top as floor. Nothing here asked it: L21 asks a wall against a STAIR\'s hole,\nand `partition_bounds.hole_cuts` a wall over a hole in its own floor (roadmap 114).\n\n### Added\n- layout_lint L27 (advisory WARN): a wall under a hole in its ceiling. `ceiling_holes` reads every authored hole the\n  builder cuts -- `slab_holes`, and the floor_hole and hatch links that cut the slab, read as `_vertical_links` reads\n  them; a hole authored in both lists is one hole carrying both -- and `ceiling_hole_walls` names each partition, as\n  `built_walls` stands it, that reaches into one in its own ceiling: how far its thickness reaches past the hole\'s edge\n  and along how much of its run. Touching the edge (`CEILING_HOLE_TOL_M`, `STALE_TOL_M`\'s 0.02 m) is the hole\'s\n  enclosure, not a wall under it. Built walls, not authored ones: a wall over a hole in its own floor is cut there\n  first, and two storey-1 walls of final_stand\'s and cbp_town_finale\'s atriums that a census of raw partitions counted\n  stand nowhere under the hole above.\n- `open_floor_rules._clear_holes`: a hole a WALL row\'s new wall would stand under slides across the wall, whole grid\n  cells, toward the side holding its centre, until it opens into the one room below that holds its centre and no wall\n  stands under it -- the hole moves, not the wall (L21\'s rule for a stair) -- every ref with it. It stays over the same\n  rooms above and below, off every other hole and stair walk, and moves no wall of the storey above; else the pair is\n  taken back whole, as for a lint FAIL. `apply` also slides a hole off a standing wall whose two sides are a WALL row\'s\n  pair, so running the migration again converges a library walled before the rule; a wall the table does not own\n  keeps its hole, and L27 names it.\n\n### Library\n- `migrate_open_floor_rules.py`, run again: the six delis\' drops slid +0.5 m in x, to (8.5, -4) -- x 7.4..9.6, in the\n  kitchen, 0.225 m clear of the wall\'s face -- slab hole and link together.\n- Refurnished (`migrate_furnish_recipes.py`): corner_deli_heist_01, cr_deli and night_deli move, their storey-1 dining\n  table having stood within furnish\'s 0.3 m of the slid hole -- in each, 6 pieces moved and one chair out; deli_a01,\n  deli_a02 and deli_a03 move none. The rest of the library refurnished changes nothing.\n- L27 on the library: the six delis\' walls gone; three walls that stood under a hole before the table, named and not\n  moved -- final_stand\'s ground-floor wall at y -3 under its atrium (0.30 m into it, along 10 m),\n  cbp_town_finale_midbalanced_schemafixed\'s at y 10 (0.30 m, 28 m), and bank\'s at x 4, its centreline on its atrium\'s\n  edge (0.15 m, 6 m). No lint FAIL before or after in any of the six.\n\n### Changed\n- `migrate_open_floor_rules.py`\'s docstring says what running it again does.\n- Tests: test_ceiling_holes.py (9). All 9 fail on 0.234.0; with L27 alone beside 0.234.0\'s table, the 5 that ask the\n  table fail -- the hole left over the wall it lays and over one standing, the pair not refused, the library\'s six\n  delis and a preset deli carrying the drop over the kitchen wall.\n\n'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    raw = (DC / name).read_bytes()
    if _sha(raw) != PINS[name]:
        raise SystemExit("REFUSED: deli_counter/%s is %s, not the %s this patch was written against; nothing written"
                         % (name, _sha(raw), PINS[name]))
    if b"\r\n" in raw:
        raise SystemExit("REFUSED: deli_counter/%s has CRLF endings; these edits are LF" % name)
    return raw.decode("utf-8")


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: deli_counter/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text
    for name in NEW_FILES:
        p = DC / name
        if p.exists() and p.read_text(encoding="utf-8") != NEW_FILES[name]:
            raise SystemExit("REFUSED: deli_counter/%s exists and is not this patch's; nothing written" % name)
    v = DC / "VERSION"
    if v.read_text(encoding="utf-8").strip() != "Deli Counter 0.234.0":
        raise SystemExit("REFUSED: VERSION reads %r, not Deli Counter 0.234.0; nothing written" % v.read_text())
    cl = DC / "CHANGELOG.md"
    ctext = cl.read_bytes().decode("utf-8")
    if not ctext.startswith("## [0.234.0]"):
        raise SystemExit("REFUSED: CHANGELOG.md does not open on 0.234.0; nothing written")
    for name, text in out.items():
        (DC / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (DC / name).write_bytes(text.encode("utf-8"))
    v.write_text("Deli Counter 0.235.0", encoding="utf-8")
    cl.write_bytes((CHANGELOG + ctext).encode("utf-8"))
    print("Deli Counter 0.235.0 applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in deli_counter/: "
          "migrate_open_floor_rules.py, migrate_furnish_recipes.py, catalog.py, the suite, build.py --all, check.py"
          % (len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
